import{_ as s,a0 as o,w as a,s as u,ao as p,I as n,x as t,a1 as r,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"工程師和市場營銷人員之間能夠相互學習什麼？ | LCTT x X-CMD","titleTemplate":false,"description":"工程師和市場營銷人員之間能夠相互學習什麼？ | LCTT (201704) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"工程師和市場營銷人員之間能夠相互學習什麼？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"工程師和市場營銷人員之間能夠相互學習什麼？ | LCTT (201704) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201704/20170110 What engineers and marketers can learn from each other","title":"工程師和市場營銷人員之間能夠相互學習什麼？","tag":"201704","desc":""},"relativePath":"201704/20170110 What engineers and marketers can learn from each other.md","filePath":"[post].md"}'),m={name:"201704/20170110 What engineers and marketers can learn from each other.md"};function d(f,e,T,g,k,C){const l=o("Link");return a(),u("div",null,[e[24]||(e[24]=p('<h1 id="工程師和市場營銷人員之間能夠相互學習什麼" tabindex="-1">工程師和市場營銷人員之間能夠相互學習什麼？ <a class="header-anchor" href="#工程師和市場營銷人員之間能夠相互學習什麼" aria-label="Permalink to “工程師和市場營銷人員之間能夠相互學習什麼？”">​</a></h1><blockquote><p>營銷人員覺得工程師在工作中都太嚴謹了；而工程師則認為營銷人員毫無用處。但是他們都錯了。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/images/business/BIZ_fortunecookie3.png?itok=dlRX4vO9" alt="What engineers and marketers can learn from each other" title="What engineers and marketers can learn from each other"></p><p>圖片來源：opensource.com</p><p>在 B2B 行業從事多年的銷售實踐過程中，我經常聽到工程師對營銷人員的各種誤解。下面這些是比較常見的：</p><ul><li>“搞市場營銷真是浪費錢，還不如把更多的資金投入到實際的產品開發中來。”</li><li>“那些營銷人員只是一個勁兒往牆上貼各種廣告，還祈禱着它們不要掉下來。這麼做有啥科學依據啊？”</li><li>“誰願意去看哪些廣告啊？”</li><li>“對待一個營銷人員最好的辦法就是不聽，不看，也不理睬。”</li></ul><p>這是我最感興趣的一點：</p><p><em>“市場營銷無足輕重。”</em></p><p>最後一點説的不對，而且不僅如此，它實際上是阻礙一個公司創新的巨大絆腳石。</p><p>我來跟大家解釋一下原因吧。</p><h3 id="看到自己的身影" tabindex="-1">看到自己的身影 <a class="header-anchor" href="#看到自己的身影" aria-label="Permalink to “看到自己的身影”">​</a></h3><p>這些工程師的的評論讓我十分的苦惱，因為我從中看到了自己當年的身影。</p><p>你們知道嗎？我曾經也跟你們一樣是一位自豪的技術極客。我在 Rensselaer Polytechnic 學院的電氣工程專業本科畢業後便在美國空軍擔任軍官開始了我的職業生涯，而且美國空軍在那段時間還發動了沙漠風暴行動。在那裏我主要負責開發並部屬一套智能的實時戰況分析系統，用於綜合幾個的數據源來構建出戰場態勢。</p><p>在我離開空軍之後，我本打算去麻省理工學院攻讀博士學位。但是上校強烈建議我去報讀這個學校的商學院。“你真的想一輩子待實驗室裏嗎？”他問我。“你想就這麼去大學裏當個教書匠嗎？Jackie ，你在組織管理那些複雜的工作中比較有天賦。我覺得你非常有必要去了解下 MIT 的斯隆商學院。”</p><p>我覺得自己也可以同時參加一些 MIT 技術方面的課程，因此我採納了他的建議。然而，如果要參加市場營銷管理方面的課程，我還有很長的路要走，這完全是在浪費時間。因此，在日常工作學習中，我始終是用自己所擅長的分析能力去解決一切問題。</p><p>不久後，我在波士頓諮詢集團公司做諮詢顧問工作。在那六年的時間裏，我經常聽到大家對我的評論： “Jackie ，你太沒遠見了。考慮問題也不夠周全。你總是通過自己的分析去找答案。”</p><p>確實如此啊，我很贊同他們的想法——因為這個世界的工作方式本該如此，任何問題都要基於數據進行分析，不對嗎？直到現在我才意識到（我多麼希望自己早一些發現自己的問題）自己以前慣用的分析問題的方法遺漏了很多重要的東西：開放的心態、藝術修養、情感——人和創造性思維相關的因素。</p><p>我在 2001 年 9 月 11 日加入達美航空公司不久後，被調去管理消費者市場部門，之前我意識到的所有問題變得更加明顯。市場方面本來不是我的強項，但是在公司需要的情況下，我也願意出手相肋。</p><p>但是突然之間，我一直慣用的方法獲取到的分析結果卻與實際情況完全相反。這個問題導致上千人（包括航線內外的人）受到影響。我忽略了一個很重要的人本身的情感因素。我所面臨的問題需要各種各樣的解決方案才能處理，而不是簡單的從那些死板的數據中就能得到答案。</p><p>那段時間，我快速地學到了很多東西，因為如果我們想把達美航空公司恢復到正常狀態，還需要做很多的工作——市場營銷更像是一個以解決問題為導向、以用户為中心的充滿挑戰性的大工程，只是銷售人員和工程師這兩大陣營都沒有迅速地意識到這個問題。</p><h3 id="兩大文化差異" tabindex="-1">兩大文化差異 <a class="header-anchor" href="#兩大文化差異" aria-label="Permalink to “兩大文化差異”">​</a></h3>',21)),n("p",null,[e[1]||(e[1]=t("工程管理和市場營銷之間的這個“巨大鴻溝”確實是根深蒂固的，這跟（著名的科學家、小説家） C.P. Snow 提出的",-1)),r(l,{href:"https://en.wikipedia.org/wiki/The_Two_Cultures#Implications_and_influence"},{default:i(()=>[...e[0]||(e[0]=[t("“兩大文化差異”問題",-1)])]),_:1}),e[2]||(e[2]=t("很相似。具有科學素質的工程師和具有藝術細胞的營銷人員操着不同的語言，不同的文化觀念導致他們不同的價值取向。",-1))]),n("p",null,[e[4]||(e[4]=t("但是，事實上他們比想像中有更多的相似之處。一個由微軟、谷歌和美國國家科學基金會共同贊助的華盛頓大學的",-1)),r(l,{href:"https://faculty.washington.edu/ajko/papers/Li2015GreatEngineers.pdf"},{default:i(()=>[...e[3]||(e[3]=[t("最新研究",-1)])]),_:1}),e[5]||(e[5]=t("發現了“一個偉大軟件工程師必須具備哪些優秀的素質”，毫無疑問，一個偉大的銷售人員同樣也應該具備這些素質。例如，專家們給出的一些優秀品質如下：",-1))]),e[25]||(e[25]=p('<ul><li>充滿激情</li><li>性格開朗</li><li>強烈的好奇心</li><li>技藝精湛</li><li>解決複雜難題的能力</li></ul><p>這些只是其中很小的一部分！當然，並不是所有的素質都適用於市場營銷人員，但是如果用文氏圖來表示這“兩大文化”的交集，就很容易看出營銷人員和工程師之間的關係要遠比我們想像中密切得多。他們都是竭力去解決與用户或客户相關的難題，只是他們所採取的方式和角度不一致罷了。</p><p>看到上面的那幾點後，我深深的陷入思考：<em>要是這兩類員工彼此之間再多瞭解對方一些會怎樣呢？這會給公司帶來很強大的動力吧？</em></p><p>確實如此。我在紅帽公司就親眼看到過樣的情形，我身邊都是一些早些年肯定被我當成“想法瘋狂”而無視的人。而且我猜銷售人員看到工程師後（同時或某一次），心想，“這些數據呆瓜，真是隻見樹木不見森林。”</p><p>現在我才明白了公司裏有這兩種人才的重要性。在現實工作當中，工程師和營銷人員都是圍繞着客户、創新及數據分析來完成工作。如果他們能夠懂得相互尊重、彼此理解、相輔相成，那麼我們將會看到公司裏所產生的那種積極強大的動力，這種超乎尋常的革新力量要遠比兩個獨立的團隊強大得多。</p><h3 id="聽一聽瘋子-和呆瓜-的想法" tabindex="-1">聽一聽瘋子（和呆瓜）的想法 <a class="header-anchor" href="#聽一聽瘋子-和呆瓜-的想法" aria-label="Permalink to “聽一聽瘋子（和呆瓜）的想法”">​</a></h3><p>成功案例：《開放式組織》</p><p>在紅帽任職期間，我的主要工作就是想辦法提升公司的品牌影響力——但是就是給我一百萬年我也不會想到讓公司的 CEO 去寫一本書。我把公司多個部門的“想法瘋狂”的同事召集在一起，希望他們幫我設計出一個新穎的解決方案來提升公司的影響力，結果他們提出讓公司的 CEO 寫書這樣一個想法。</p>',8)),n("p",null,[e[7]||(e[7]=t("當我聽到這個想法的時候，我很快意識到這正是典型的紅帽方式：它將對整個開源社區的從業者帶來很重要的參考價值，同時也有助於宣揚開源精神。通過優先考慮這兩方面的作用，我們提升了紅帽在整個開源軟件世界中的品牌價值——紅帽是一個可靠的隨時準備着為客户在",-1)),r(l,{href:"https://opensource.com/open-organization/16/7/future-belongs-open-leaders"},{default:i(()=>[...e[6]||(e[6]=[t("數字化顛覆",-1)])]),_:1}),e[8]||(e[8]=t("年代指明方向的公司。",-1))]),e[26]||(e[26]=n("p",null,"這一點才是主要的：確切的説是指導紅帽工程師解決代碼問題的共同精神力量。 Red Hatters 小組敦促我出版《開放式組織》，這顯示出來自內部和外部社區的程序員共同推動整個開源社區發展的強大動力之一：那就是強烈的共享慾望。",-1)),e[27]||(e[27]=n("p",null,"最後，要把《開放式組織》這本書完成，還需要大家的共同能力，包括工程師們強大的數據分析能力和營銷人員美好的藝術素養。這個項目讓我更加堅定自己的想法，工程師和營銷人員有更多的相似之處。",-1)),e[28]||(e[28]=n("p",null,"但是，有些東西我還得強調下：開放模式的實現，要求公司上下沒有任何偏見，不能偏袒工程師和市場營銷人員任何一方文化。一個更加理想的開放式環境能夠促使員工之間和平共處，並在這個組織規定的範圍內點燃大家的熱情。",-1)),e[29]||(e[29]=n("p",null,"這對我來説如春風拂面。",-1)),e[30]||(e[30]=n("hr",null,null,-1)),e[31]||(e[31]=n("p",null,"作者簡介：",-1)),e[32]||(e[32]=n("p",null,[n("img",{src:"https://opensource.com/sites/default/files/styles/profile_pictures/public/pictures/portrait_jackieyeaney_400x600.jpg?itok=zV4bnrzI",alt:""})],-1)),e[33]||(e[33]=n("p",null,"Jackie Yeaney —— Ellucian 公司市場總監",-1)),e[34]||(e[34]=n("hr",null,null,-1)),n("p",null,[e[10]||(e[10]=t("via: ",-1)),r(l,{href:"https://opensource.com/open-organization/17/1/engineers-marketers-can-learn"},{default:i(()=>[...e[9]||(e[9]=[t("https://opensource.com/open-organization/17/1/engineers-marketers-can-learn",-1)])]),_:1})]),n("p",null,[e[15]||(e[15]=t("作者：",-1)),r(l,{href:"https://opensource.com/users/jackie-yeaney"},{default:i(()=>[...e[11]||(e[11]=[t("Jackie Yeaney",-1)])]),_:1}),e[16]||(e[16]=t(" 譯者：",-1)),r(l,{href:"https://github.com/rusking"},{default:i(()=>[...e[12]||(e[12]=[t("rusking",-1)])]),_:1}),e[17]||(e[17]=t(" 校對：",-1)),r(l,{href:"https://github.com/Bestony"},{default:i(()=>[...e[13]||(e[13]=[t("Bestony",-1)])]),_:1}),e[18]||(e[18]=t(", ",-1)),r(l,{href:"https://github.com/wxy"},{default:i(()=>[...e[14]||(e[14]=[t("wxy",-1)])]),_:1})]),n("p",null,[e[21]||(e[21]=t("本文由 ",-1)),r(l,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[19]||(e[19]=[t("LCTT",-1)])]),_:1}),e[22]||(e[22]=t(" 原創編譯，",-1)),r(l,{href:"https://linux.cn/"},{default:i(()=>[...e[20]||(e[20]=[t("Linux中國",-1)])]),_:1}),e[23]||(e[23]=t(" 榮譽推出",-1))])])}const P=s(m,[["render",d]]);export{y as __pageData,P as default};
